set -u
R=/scratch/jjyeung/orch_n30
date -u +%TZ
mkdir -p $R/sb_drev7; cp $R/sb_cursor_probe/AGENTS.md $R/sb_drev7/AGENTS.md
echo  | base64 -d > $R/sb_drev7/PROMPT.md
cd $R/sb_drev7 && tmux new-session -d -s sb_drev7 "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
mkdir -p $R/sb_rkrev2; cp $R/sb_cursor_probe/AGENTS.md $R/sb_rkrev2/AGENTS.md
echo  | base64 -d > $R/sb_rkrev2/PROMPT.md
cd $R/sb_rkrev2 && tmux new-session -d -s sb_rkrev2 "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
sleep 3; tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "; echo; tail -3 $R/sb_queue/codexq.log
